[FormDataSourceEventHandler(formDataSourceStr(ARGSalesOrderReport, SalesTable), FormDataSourceEventType::Initialized)]
public static void ARGSalesOrderReport_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)        
{     
    sender.queryBuildDataSource().sortClear();

    sender.queryBuildDataSource().addSortField(fieldNum(SalesTable,CreatedDateTime),SortOrder::Descending);
}
